create or replace function public.app_submit_registration(p_username text,p_password text,p_full_name text,p_phone text,p_email text,p_requested_role text,p_building_id uuid default null,p_unit_no integer default null,p_area numeric default null,p_resident_count integer default null,p_new_building_name text default null,p_new_building_unit_count integer default null,p_new_building_address text default null,p_new_building_floor_count integer default null) returns jsonb language plpgsql security definer set search_path='' as $$ begin if exists(select 1 from public.app_accounts where lower(username)=lower(p_username)) then raise exception 'نام کاربری تکراری است'; end if; if p_requested_role='manager' then if nullif(btrim(p_new_building_name),'') is null then raise exception 'نام ساختمان الزامی است'; end if; if p_new_building_unit_count is null or p_new_building_unit_count<1 then raise exception 'تعداد واحد نامعتبر است'; end if; if nullif(btrim(p_new_building_address),'') is null then raise exception 'آدرس ساختمان الزامی است'; end if; if p_new_building_floor_count is null or p_new_building_floor_count<1 then raise exception 'تعداد طبقات نامعتبر است'; end if; end if; insert into public.registration_requests(username,requested_password_hash,full_name,phone,email,requested_role,building_id,unit_no,area,resident_count,new_building_name,new_building_unit_count,new_building_address,new_building_floor_count) values(p_username,extensions.crypt(p_password,extensions.gen_salt('bf')),p_full_name,p_phone,p_email,p_requested_role,p_building_id,p_unit_no,p_area,p_resident_count,p_new_building_name,p_new_building_unit_count,p_new_building_address,p_new_building_floor_count); return jsonb_build_object('success',true); end; $$;
